// Developer diagnostics in the browser console. User-facing messages come from
// ERROR_TEXT (utils/uiText.js) and ApiError (services/apiError.js), never from here.
//
// An ApiError is logged as its code, HTTP status and message only: its `detail` (the raw
// server response) is left out so that server internals never reach the console by default.

import { ApiError } from "@/services/apiError";

export function describeError(error) {
  if (error instanceof ApiError) {
    return `${error.code}${error.status ? ` (HTTP ${error.status})` : ""}: ${error.message}`;
  }
  return error;
}

// logError("schedule", err) -> console.error("[schedule] Unable to load…", <error>)
export function logError(scope, action, error) {
  console.error(`[${scope}] ${action}`, describeError(error));
}
