<template>
    <div class="sc-wrap">
        <!-- fixed top: header, project, filter cards -->
        <div class="sc-fixed">
            <div class="sc-head">
                <div class="sc-icon"><v-icon icon="mdi-calendar-clock-outline" size="22" /></div>
                <div class="sc-titles">
                    <h2 class="sc-title">{{ text.title }}</h2>
                    <div class="sc-sub">{{ text.subtitle }}</div>
                </div>

                <div class="sc-toggle" role="group" aria-label="Project scope">
                    <button type="button" :class="{ on: scope === 'single' }" :aria-pressed="scope === 'single' ? 'true' : 'false'" @click="scope = 'single'">
                        <v-icon icon="mdi-briefcase-outline" size="16" /> {{ text.scopeSingle }}
                    </button>
                    <button type="button" :class="{ on: scope === 'all' }" :aria-pressed="scope === 'all' ? 'true' : 'false'" @click="scope = 'all'">
                        <v-icon icon="mdi-briefcase-account-outline" size="16" /> {{ text.scopeAll }}
                    </button>
                </div>

                <v-autocomplete v-if="scope === 'single'" v-model="project" class="sc-project" :items="projects"
                    :loading="loadingProjects" prepend-inner-icon="mdi-briefcase-outline" clearable variant="outlined"
                    density="compact" hide-details>
                    <template #label>{{ text.project }} <span class="sc-req">*</span></template>
                    <template #no-data>
                        <div class="sc-nodata">
                            {{ text.noProjects }}
                            <button type="button" class="btn-ghost btn-sm" @click="loadProjects(true)">{{ text.retry }}</button>
                        </div>
                    </template>
                </v-autocomplete>

                <div v-if="scope === 'single' && (loading || fetching || loadingProjects)" class="sc-status" role="status">
                    <v-progress-circular indeterminate size="14" width="2" />
                    <span v-if="loading">{{ text.loadedLabel }} {{ tasks.length }} {{ text.of }} {{ total || "…"
                        }}</span>
                    <span v-else-if="fetching">{{ text.loadingDates }}</span>
                    <span v-else>{{ text.loadingProjects }}</span>
                </div>
                <button v-if="active" type="button" class="sc-refresh" :disabled="loading" title="Reload" aria-label="Reload schedule" @click="loadTasks(true)">
                    <v-icon icon="mdi-refresh" size="18" :class="{ spin: loading }" />
                </button>
            </div>

            <div v-if="scope === 'all'" class="dw-alert sc-scope" role="status">
                <v-icon icon="mdi-account-check-outline" size="18" />
                <span>
                    <b>All projects</b> includes only {{ scopeLabel }}<template v-if="assigned.length"> ({{ assigned.length }})</template>.
                    Projects you can see but aren't assigned to are excluded.
                </span>
                <span class="dw-spacer" />
                <span v-if="assigned.length" class="sc-progress">
                    <span v-if="loading" class="dw-spinner" aria-hidden="true" />
                    Loaded {{ projectsDone - failedProjects.length }} of {{ assigned.length }} projects · {{ tasks.length }} items
                </span>
            </div>
            <div v-if="scope === 'all' && failedProjects.length" class="dw-alert dw-alert--warning sc-scope" role="alert">
                <v-icon icon="mdi-alert-outline" size="18" />
                <span>
                    <b>{{ failedProjects.length }} {{ failedProjects.length === 1 ? "project" : "projects" }} couldn't be loaded</b>
                    ({{ failedProjects.slice(0, 3).join(", ") }}<template v-if="failedProjects.length > 3">…</template>). Items from the other projects are shown.
                </span>
                <span class="dw-spacer" />
                <button type="button" class="btn-ghost btn-sm" :disabled="loading" @click="loadTasks(true)"><v-icon icon="mdi-refresh" /> Retry</button>
            </div>

            <div v-if="active && !scopeBlocked" class="sc-tiles">
                <button v-for="f in filters" :key="f.id" class="sc-tile" :class="{ active: filterId === f.id }"
                    :style="{ '--c': f.color }" @click="filterId = f.id">
                    <span class="sc-tile-icon"><v-icon :icon="f.icon" size="20" /></span>
                    <span class="sc-tile-body">
                        <span class="sc-tile-n">{{ loaded || tasks.length ? counts[f.id] + (lazy && pending && f.id !== "all" ? "+" : "") : "–" }}</span>
                        <span class="sc-tile-l">{{ f.short }}</span>
                    </span>
                </button>
            </div>

            <div v-if="lazy && pending && tasks.length" class="sc-note">
                {{ text.datesNote.replace("{n}", tasks.length - pending).replace("{t}", tasks.length) }}
            </div>

            <div v-if="loading" class="sc-bar" :class="{ 'sc-bar--wait': !total }">
                <span :style="{ width: pct + '%' }" />
            </div>
        </div>

        <div class="sc-panel sc-results">
            <StateMessage
                v-if="scope === 'all' && scopeError"
                tone="error"
                icon="mdi-power-plug-off-outline"
                :title="errorText.loadProjectsTitle"
                :message="scopeError"
                action-label="Try again"
                @action="loadTasks(true)"
            />
            <StateMessage
                v-else-if="scope === 'all' && loaded && !assigned.length"
                icon="mdi-briefcase-off-outline"
                title="No projects are assigned to you"
                :message="`Project Schedule shows only ${scopeLabel}. Ask a project leader to add you as a member of the project.`"
                action-label="Check again"
                @action="loadTasks(true)"
            />
            <div v-else-if="!active" class="sc-state">
                <v-icon icon="mdi-briefcase-search-outline" size="44" />
                <div class="sc-state-t">{{ text.pickProject }}</div>
                <div class="sc-state-s">{{ text.pickProjectHint }}</div>
            </div>

            <div v-else-if="loading && !tasks.length" class="sc-state">
                <v-progress-circular indeterminate size="30" width="3" color="primary" />
                <div class="sc-state-s">{{ text.loading }}</div>
                <div v-if="total" class="sc-state-s">{{ text.loadedLabel }} 0 {{ text.of }} {{ total }}</div>
            </div>

            <template v-else-if="loaded || tasks.length">
                <div v-if="!tasks.length" class="sc-state">
                    <v-icon icon="mdi-clipboard-text-off-outline" size="44" />
                    <div class="sc-state-s">{{ text.noItems }}</div>
                </div>

                <template v-else>
                    <div class="sc-summary">
                        <span class="sc-dot" :style="{ background: currentFilter.color }" />
                        <b>{{ shown.length }}</b> {{ text.of }} {{ tasks.length }} {{ text.items }}
                        <span class="sc-fname">{{ currentFilter.label }}</span>
                        <span v-if="capped" class="sc-fname">{{ text.cappedNote.replace("{n}", tasks.length) }}</span>

                        <div class="sc-tools">
                            <select v-for="k in colKeys" :key="k" v-model="colFilter[k]" class="sc-select" :aria-label="allLabel(k)">
                                <option value="">{{ allLabel(k) }}</option>
                                <option v-for="o in colOptions[k]" :key="o" :value="o">{{ o }}</option>
                            </select>
                            <div class="sc-toggle">
                                <button type="button" :class="{ on: view === 'table' }" :aria-pressed="view === 'table' ? 'true' : 'false'" @click="view = 'table'">
                                    <v-icon icon="mdi-table" size="16" /> {{ text.viewTable }}
                                </button>
                                <button type="button" :class="{ on: view === 'timeline' }" :aria-pressed="view === 'timeline' ? 'true' : 'false'" @click="view = 'timeline'">
                                    <v-icon icon="mdi-chart-gantt" size="16" /> {{ text.viewTimeline }}
                                </button>
                            </div>
                        </div>
                    </div>

                    <div v-if="!shown.length" class="sc-state sc-state--compact">
                        <v-icon icon="mdi-check-circle-outline" size="40" />
                        <div class="sc-state-t">{{ text.empty }}</div>
                        <div class="sc-state-s">{{ text.emptyHint }}</div>
                    </div>

                    <template v-else>
                        <div v-if="view === 'table'" class="sc-table-wrap">
                            <table class="sc-table">
                                <thead>
                                    <tr>
                                        <th>{{ text.name }}</th>
                                        <th v-if="scope === 'all'">{{ text.projectCol }}</th>
                                        <th>{{ text.type }}</th>
                                        <th>{{ text.state }}</th>
                                        <th v-for="c in dateColumns" :key="c.key">{{ c.label }}</th>
                                        <th class="sc-r">{{ currentFilter.daysLabel }}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-for="r in pageRows" :key="r.id">
                                        <td class="sc-main">
                                            <div class="sc-name" :title="r.title">{{ r.title }}</div>
                                            <div class="sc-id">{{ r.name }}</div>
                                        </td>
                                        <td v-if="scope === 'all'" class="sc-date">{{ r.project || "–" }}</td>
                                        <td><span class="sc-type">{{ r.objType }}</span></td>
                                        <td>
                                            <span class="sc-chip" :style="{ '--c': stateColor(r.state) }">{{ r.state ||
                                                "–" }}</span>
                                        </td>
                                        <td v-for="c in dateColumns" :key="c.key" class="sc-date">
                                            {{ c.formatter(r[c.key]) || (r.detailed === false ? "…" : "–") }}
                                        </td>
                                        <td class="sc-r">
                                            <span v-if="r.days != null" class="sc-badge"
                                                :style="{ '--c': currentFilter.color }">{{ r.days }} d</span>
                                            <span v-else class="sc-date">–</span>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                        <ScheduleTimeline v-else :rows="pageRows" :range-rows="shown"/>

                        <div class="sc-pager">
                            <div class="sc-pager-size">
                                {{ text.rowsPerPage }}
                                <select v-model.number="pageSize" class="sc-select" :aria-label="text.rowsPerPage">
                                    <option v-for="n in pageSizes" :key="n" :value="n">{{ n }}</option>
                                </select>
                                <span class="sc-range">{{ rangeFrom }}–{{ rangeTo }} {{ text.of }} {{ shown.length
                                    }}</span>
                            </div>
                            <v-pagination v-model="page" :length="pages" :total-visible="5" density="comfortable"
                                rounded="lg" />
                        </div>
                    </template>
                </template>
            </template>
        </div>
    </div>
</template>

<script>
import scheduleApi from "@/services/scheduleApi";
import ScheduleTimeline from "@/components/ScheduleTimeline.vue";
import { applySchedule } from "@/utils/scheduleRules";
import {
    SCHEDULE_FILTERS,
    SCHEDULE_DATE_COLUMNS,
    DEFAULT_SCHEDULE_FILTER,
    SCHEDULE_STATE_COLORS,
    SCHEDULE_STATE_DEFAULT_COLOR,
} from "@/utils/dashboardData";
import { ERROR_TEXT, SCHEDULE_TEXT } from "@/utils/uiText";
import { logError } from "@/utils/logger";
import { toastBus } from "@/components/common/toastBus";
import { toRaw } from "vue";
import { cacheGet, cacheSet } from "@/utils/idbCache";
import StateMessage from "@/components/common/StateMessage.vue";
import { PROJECT_SCOPE } from "@/config/platformConfig";
import { useDashboardStore } from "@/store/dashboardStore";

// "All projects" results are cached per tenant + user + security context (never shared
// between users) and invalidated when the set of associated projects changes.
const ALL_KEY = "schedule-assigned-v2";
const ALL_TTL = 6 * 3600 * 1000; // a saved "all projects" list is reused for 6 hours
let memo = null; // same data kept in memory while the page is open

const PAGE_SIZES = [10, 25, 50, 100];
const inflight = new Set(); // task ids whose dates are being loaded

export default {
    name: "ScheduleView",
    components: { ScheduleTimeline, StateMessage },
    setup() {
        return { store: useDashboardStore() };
    },
    data() {
        return {
            text: SCHEDULE_TEXT,
            errorText: ERROR_TEXT,
            filters: SCHEDULE_FILTERS,
            dateColumns: SCHEDULE_DATE_COLUMNS,
            pageSizes: PAGE_SIZES,
            scope: "single", // "single" project or "all" projects
            capped: false,
            fetching: 0, // date requests running
            projects: [],
            project: null,
            filterId: DEFAULT_SCHEDULE_FILTER,
            tasks: [],
            total: 0,
            page: 1,
            pageSize: 10,
            view: "table",
            colFilter: { project: "", objType: "", state: "" },
            loadingProjects: false,
            loading: false,
            loaded: false,
            req: 0,
            assigned: [], // [{ name, id }] projects associated with the user
            projectsDone: 0,
            failedProjects: [],
            scopeError: "",
            scopeLabel: PROJECT_SCOPE.label,
        };
    },
    computed: {
        // "All projects" can't show results: identity missing or no associated projects
        scopeBlocked() {
            return this.scope === "all" && (!!this.scopeError || (this.loaded && !this.assigned.length));
        },
        active() {
            return this.scope === "all" || !!this.project;
        },
        lazy() {
            return this.scope === "all"; // dates load per page
        },
        pending() {
            return this.tasks.filter((t) => !t.detailed).length;
        },
        colKeys() {
            return this.scope === "all" ? ["project", "objType", "state"] : ["objType", "state"];
        },
        currentFilter() {
            return this.filters.find((f) => f.id === this.filterId);
        },
        shown() {
            const c = this.colFilter;
            return applySchedule(this.tasks, this.filterId, Date.now(), !this.lazy).filter(
                (r) =>
                    (!c.project || r.project === c.project) &&
                    (!c.objType || r.objType === c.objType) &&
                    (!c.state || r.state === c.state),
            );
        },
        colOptions() {
            const o = {};
            this.colKeys.forEach((k) => {
                o[k] = [...new Set(this.tasks.map((t) => t[k]).filter(Boolean))].sort();
            });
            return o;
        },
        counts() {
            return Object.fromEntries(
                this.filters.map((f) => [f.id, applySchedule(this.tasks, f.id, Date.now(), !this.lazy).length]),
            );
        },
        pct() {
            return this.total ? Math.min(100, Math.round((this.tasks.length / this.total) * 100)) : 0;
        },
        pages() {
            return Math.max(1, Math.ceil(this.shown.length / this.pageSize));
        },
        pageRows() {
            const s = (this.page - 1) * this.pageSize;
            return this.shown.slice(s, s + this.pageSize);
        },
        rangeFrom() {
            return this.shown.length ? (this.page - 1) * this.pageSize + 1 : 0;
        },
        rangeTo() {
            return Math.min(this.page * this.pageSize, this.shown.length);
        },
    },
    watch: {
        project() {
            this.loadTasks();
        },
        scope() {
            this.loadTasks();
        },
        pageRows(rows) {
            this.ensureDates(rows);
        },
        filterId() {
            this.page = 1;
        },
        pageSize() {
            this.page = 1;
        },
        colFilter: {
            deep: true,
            handler() {
                this.page = 1;
            },
        },
        pages(n) {
            if (this.page > n) this.page = n; // rows were added/removed
        },
    },
    mounted() {
        this.loadProjects();
    },
    beforeUnmount() {
        this.persist();
    },
    methods: {
        stateColor(state) {
            return SCHEDULE_STATE_COLORS[String(state || "").toLowerCase()] || SCHEDULE_STATE_DEFAULT_COLOR;
        },
        merge(list) {
            const m = new Map(list.map((r) => [r.id, r]));
            this.tasks = this.tasks.map((t) => m.get(t.id) || t);
        },
        // loads the dates of rows that don't have them yet (current page, or everything)
        async ensureDates(rows, flushEvery) {
            if (!this.lazy) return;
            const need = rows.filter((r) => !r.detailed && !inflight.has(r.id));
            if (!need.length) return;
            need.forEach((r) => inflight.add(r.id));
            const id = this.req;
            this.fetching++;
            try {
                await scheduleApi.loadDetails(
                    need,
                    (list) => {
                        if (id === this.req) this.merge(list);
                    },
                    flushEvery,
                );
            } finally {
                need.forEach((r) => inflight.delete(r.id));
                this.fetching--;
                if (!this.fetching) this.persist();
            }
        },
        loadAllDates(n = Infinity) {
            this.ensureDates(this.tasks.filter((t) => !t.detailed).slice(0, n), 20);
        },
        allLabel(k) {
            return k === "project" ? this.text.allProjects : k === "objType" ? this.text.allTypes : this.text.allStates;
        },
        // "Single project" lists only the projects assigned to the current user
        async loadProjects(force = false) {
            this.loadingProjects = true;
            this.projects = [];
            try {
                const list = await scheduleApi.fetchAssignedProjects({ force: force === true });
                this.projects = list.map((p) => p.name);
                if (this.project && !this.projects.includes(this.project)) this.project = null;
            } catch (e) {
                toastBus.emit(e?.code === "NO_USER" ? this.text.noIdentity : this.text.projectsFailed, "error");
            } finally {
                this.loadingProjects = false;
            }
        },
        // saves the "all projects" list (with the dates read so far) in the browser
        persist() {
            if (this.scope !== "all" || !this.loaded) return;
            if (this.failedProjects.length) return; // never cache a partial result
            memo = {
                at: memo?.at || Date.now(),
                scope: this.store.cacheScope,
                projects: this.assigned.map((p) => p.name),
                tasks: toRaw(this.tasks),
                total: this.total,
                capped: this.capped,
            };
            cacheSet(`${ALL_KEY}|${this.store.cacheScope}`, memo);
        },
        async loadTasks(force = false) {
            const id = ++this.req; // always invalidates any request still in flight
            this.tasks = [];
            this.total = 0;
            this.page = 1;
            this.loaded = false;
            this.loading = false;
            this.capped = false;
            inflight.clear();
            this.colFilter = { project: "", objType: "", state: "" };
            if (!this.active) return;
            // only projects assigned to the user can be loaded
            if (this.scope === "single" && !this.projects.includes(this.project)) return;
            this.failedProjects = [];
            this.scopeError = "";
            this.projectsDone = 0;
            if (this.scope === "all") {
                // 1) projects associated with the current user (FR-16 / FR-20)
                this.loading = true;
                try {
                    this.assigned = await scheduleApi.fetchAssignedProjects({ force: force === true });
                } catch (e) {
                    if (id !== this.req) return;
                    this.loading = false;
                    this.scopeError = e?.code === "NO_USER"
                        ? "Your 3DEXPERIENCE identity is not available, so your projects can't be determined."
                        : "Check your connection and try again.";
                    return;
                }
                if (id !== this.req) return;
                if (!this.assigned.length) {
                    this.loading = false;
                    this.loaded = true;
                    return;
                }
                // 2) cached items for exactly this user and project set
                if (force !== true) {
                    const scopeKey = this.store.cacheScope;
                    const saved = (memo?.scope === scopeKey ? memo : null) || (await cacheGet(`${ALL_KEY}|${scopeKey}`));
                    if (id !== this.req) return;
                    const sameProjects = saved && JSON.stringify(saved.projects) === JSON.stringify(this.assigned.map((p) => p.name));
                    if (saved && sameProjects && saved.scope === scopeKey && Date.now() - saved.at < ALL_TTL) {
                        memo = saved;
                        this.tasks = saved.tasks;
                        this.total = saved.total;
                        this.capped = saved.capped;
                        this.projectsDone = this.assigned.length;
                        this.loaded = true;
                        this.loading = false;
                        this.loadAllDates(); // only tasks without dates are read
                        return;
                    }
                }
            }
            this.loading = true;
            // the search index has no planned/actual dates for tasks, so dates come from the task details
            const onRows = (rows) => {
                if (id !== this.req) return;
                // a task used in two associated projects is listed once
                const have = new Set(this.tasks.map((t) => t.id));
                this.tasks = [...this.tasks, ...rows.filter((r) => !have.has(r.id) && have.add(r.id))];
            };
            const onTotal = (n) => {
                if (id === this.req) this.total += n;
            };
            try {
                const res =
                    this.scope === "all"
                        ? await scheduleApi.listTasksOfProjects(this.assigned, {
                              onRows,
                              onTotal,
                              onProject: ({ name, ok }) => {
                                  if (id !== this.req) return;
                                  this.projectsDone++;
                                  if (!ok) this.failedProjects = [...this.failedProjects, name];
                              },
                          })
                        : await scheduleApi.fetchTasks(this.project, onRows, onTotal);
                if (id === this.req) {
                    this.loaded = true;
                    this.capped = !!res?.capped;
                    if (this.scope === "all") {
                        memo = null; // fresh list
                        this.persist();
                        this.loadAllDates(); // exact counts: read every task's dates in the background
                    }
                }
            } catch (e) {
                logError("schedule", "Loading the schedule failed:", e);
                if (id === this.req) toastBus.emit(this.text.loadFailed, "error");
            } finally {
                if (id === this.req) this.loading = false;
            }
        },
    },
};
</script>

<style scoped>
.sc-scope {
    align-items: center;
}

.sc-progress {
    display: inline-flex;
    align-items: center;
    gap: var(--dw-sp-2);
    font-weight: var(--dw-fw-semibold);
    white-space: nowrap;
    color: var(--dw-text);
}

.sc-wrap {
    width: 100%;
    padding: 0 24px 24px;
    box-sizing: border-box;
}

.sc-wrap button,
.sc-wrap select,
.sc-wrap table,
.sc-wrap input {
    font-family: inherit;
}

/* fixed top block */
.sc-fixed {
    position: sticky;
    top: 0;
    z-index: 5;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 12px 0 10px;
    background: var(--dw-bg);
}

.sc-head {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.sc-icon {
    width: 38px;
    height: 38px;
    border-radius: var(--dw-radius-lg);
    background: var(--dw-primary);
    color: var(--dw-on-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
}

.sc-titles {
    flex: 1 1 200px;
    min-width: 0;
}

.sc-title {
    font-size: var(--dw-fs-lg);
    font-weight: var(--dw-fw-bold);
    margin: 0;
    line-height: 1.2;
    color: var(--dw-text);
}

.sc-sub {
    font-size: var(--dw-fs-sm);
    color: var(--dw-text-muted);
}

.sc-project {
    flex: 0 1 460px;
    min-width: 240px;
    background: var(--dw-surface);
    border-radius: var(--dw-radius);
}

.sc-refresh {
    width: 36px;
    height: 36px;
    flex: 0 0 auto;
    border: 1px solid var(--dw-border-strong);
    border-radius: var(--dw-radius-lg);
    background: var(--dw-surface);
    color: var(--dw-text-2);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
}

.sc-refresh:hover:not(:disabled) {
    background: var(--dw-bg);
    border-color: var(--dw-border-strong);
}

.spin {
    animation: sc-spin 0.9s linear infinite;
}

@keyframes sc-spin {
    to {
        transform: rotate(360deg);
    }
}

.sc-req {
    color: var(--dw-error);
    font-weight: var(--dw-fw-bold);
}

.sc-nodata {
    padding: 10px 16px;
    font-size: var(--dw-fs-base);
    color: var(--dw-text-muted);
}

.sc-nodata .btn-ghost {
    margin-left: 8px;
    color: var(--dw-primary);
    font-weight: var(--dw-fw-semibold);
}

.sc-status {
    display: flex;
    align-items: center;
    gap: 8px;
