<template>
  <div class="donut-row" ref="panel">
    <div class="chart-container">
      <apexchart
        type="donut"
        :width="chartWidth"
        height="300"
        :options="donutOptions"
        :series="chart.series"
      />
    </div>

    <div class="legend">
      <div
        v-for="(cat, i) in chart.categories"
        :key="cat"
        class="legend-row"
        @click="drill(i)"
      >
        <span
          class="dot"
          :style="{ background: chart.colors ? chart.colors[i] : PALETTE[i % PALETTE.length] }"
        />
        <span class="legend-label">{{ cat }}</span>
        <span class="legend-value">
          {{ chart.series[i].toLocaleString() }}
          {{ chart.pct ? " (" + chart.pct[i] + "%)" : "" }}
        </span>
      </div>
    </div>
  </div>
</template>

<script>
import VueApexCharts from "vue3-apexcharts";
import { PALETTE } from "@/utils/dashboardData";
import { buildDrillPayload } from "@/utils/dashboardMapper";

export default {
  name: "DonutChart",
  components: { apexchart: VueApexCharts },
  props: { chart: { type: Object, required: true } },
  emits: ["drill"],

  data() {
    return { PALETTE, chartWidth: 350, resizeObserver: null };
  },

  computed: {
    donutOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: {
            dataPointSelection: (e, ctx, cfg) => this.drill(cfg.dataPointIndex),
          },
        },
        labels: this.chart.categories,
        colors: this.chart.colors || PALETTE,
        legend: { show: false },
        dataLabels: { enabled: false },
        stroke: { width: 2, colors: ["#FFFFFF"] }, // 2px surface gap between segments
        plotOptions: { pie: { donut: { size: "55%" } } },
      };
    },
  },

  mounted() {
    this.$nextTick(() => {
      this.updateChartWidth();
      this.resizeObserver = new ResizeObserver(() => this.updateChartWidth());
      this.resizeObserver.observe(this.$refs.panel);
    });
  },

  beforeUnmount() {
    if (this.resizeObserver) this.resizeObserver.disconnect();
  },

  methods: {
    updateChartWidth() {
      if (!this.$refs.panel) return;
      const panelWidth = this.$refs.panel.clientWidth;
      if (panelWidth > 700) this.chartWidth = panelWidth * 0.55;
      else if (panelWidth > 500) this.chartWidth = panelWidth * 0.5;
      else this.chartWidth = panelWidth - 32;
    },
    drill(index) {
      this.$emit("drill", buildDrillPayload(this.chart, index));
    },
  },
};
</script>

<style scoped>
.donut-row {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.chart-container {
  flex: 1;
  min-width: 260px;
}
.legend {
  flex: 1;
  min-width: 180px;
}
.legend-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--dw-fs-sm);
  margin-bottom: 6px;
  cursor: pointer;
}
.legend-row:hover .legend-label {
  text-decoration: underline;
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.legend-label {
  flex: 1;
  color: var(--dw-text-2);
}
.legend-value {
  color: var(--dw-text-muted);
}
</style>
