// Converts a wall-clock time in the configured tenant time zone to a UTC ISO string.
// Replaces the previous hard-coded IST (+05:30) offset.
import { TIMEZONE } from "@/config/platformConfig";

function offsetMs(utcMs, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(new Date(utcMs));
  const v = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const asUtc = Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second);
  return asUtc - Math.floor(utcMs / 1000) * 1000;
}

export function zonedToUtcIso(y, m, d, h = 0, mi = 0, s = 0, timeZone = TIMEZONE) {
  const guess = Date.UTC(y, m - 1, d, h, mi, s);
  let ms = guess - offsetMs(guess, timeZone);
  // second pass handles DST transitions
  ms = guess - offsetMs(ms, timeZone);
  return new Date(ms).toISOString();
}

// "YYYY-MM-DD" -> start (00:00:00) or end (23:59:59) of that day in the tenant zone
export function dayBoundaryIso(dateStr, end = false, timeZone = TIMEZONE) {
  const [y, m, d] = String(dateStr).split("-").map(Number);
  if (!y || !m || !d) return null;
  return end ? zonedToUtcIso(y, m, d, 23, 59, 59, timeZone) : zonedToUtcIso(y, m, d, 0, 0, 0, timeZone);
}
